	agentId: string;
	watcherId: string;
	runId?: number;
	organizationId: string;
	onDone: () => void;
}) {
	const [triggersDraft, setTriggersDraft] = useState<BehaviorTriggersDraft>({
		ready: false,
		triggers: [],
	});
	const handleTriggersChange = useCallback((draft: BehaviorTriggersDraft) => {
		setTriggersDraft((prev) =>
			JSON.stringify(prev) === JSON.stringify(draft) ? prev : draft,
		);
	}, []);
	const detail = useWatcherDetail(watcherId, undefined, organizationId, {
		includeVersions: true,
	});
	const w = detail.data?.behavior;

	const skeleton = (
		<div className="flex flex-col gap-4">
			{[0, 1, 2].map((i) => (
				<Skeleton key={i} className="h-16 w-full rounded-lg" />
			))}
		</div>
	);

	const editForm = detail.isLoading ? (
		skeleton
	) : w ? (
		<CreateWatcherForm
			organizationId={organizationId}
			prefillAgentId={agentId}
			editingWatcher={{
				behavior_id: w.behavior_id,
				name: w.behavior_name,
				slug: w.slug,
				description: w.description,
				prompt: w.prompt,
				sources: w.sources,
				reaction_script: w.reaction_script,
				agent_id: w.agent_id,
				scheduler_client_id: w.scheduler_client_id,
				classifiers: w.classifiers,
				keying_config: w.keying_config,
				reactions_guidance: w.reactions_guidance,
				triggers: w.triggers,
			}}
			createFields={{
				// Full array from the multi-trigger editor — never collapse to [0].
				triggers: triggersDraft.triggers,
			}}
			triggerFields={
				<BehaviorTriggersEditor
					key={JSON.stringify(w.triggers ?? [])}
					organizationId={organizationId}
					initialTriggers={w.triggers ?? []}
					onChange={handleTriggersChange}
				/>
			}
			submitDisabled={!triggersDraft.ready}
			onClose={onDone}
			onSuccess={onDone}
			hideHeader
		/>
	) : (
		<p className="text-sm text-muted-foreground">
			Behavior not found. It may have been removed.
		</p>
	);

	return (
		<ProposalReviewShell
			resource={{ kind: "behavior", agentId, behaviorId: watcherId }}
			runId={runId}
			onDone={onDone}
		>
			{({ reviewMode, proposal }) =>
				reviewMode === "active" ? (
					// A manage_behaviors update is a PATCH. The server computes
					// `proposedAfter` (the STORED values, via the same normalizer the
					// apply handler uses), so the "after" is just `current` overlaid with
					// it — displayed == applied, no client-side coercion.
					<JsonDiff
						before={proposal?.current ?? null}
						after={{
							...(proposal?.current ?? {}),
							...(proposal?.proposedAfter ?? {}),
						}}
					/>

