69	 * `properties` and arbitrary connection `config` blobs as real object/array
70	 * literals (not `JSON.stringify` blobs), with object keys unquoted where they're
71	 * valid identifiers.
72	 */
73	function emitValue(value: unknown, indent: number): string {
74	  const pad = "  ".repeat(indent);
75	  const padInner = "  ".repeat(indent + 1);
76	  if (value === null) return "null";
77	  if (typeof value === "string") return str(value);
78	  if (typeof value === "number" || typeof value === "boolean") {
79	    return String(value);
80	  }
81	  if (Array.isArray(value)) {
82	    if (value.length === 0) return "[]";
83	    // Inline short arrays of primitives (mirrors Prettier output) so e.g.
84	    // `required: ["stage"]` and `tags: ["a", "b"]` don't sprawl over many lines.
85	    const allPrimitive = value.every(
86	      (v) =>
87	        v === null ||
88	        typeof v === "string" ||
89	        typeof v === "number" ||
90	        typeof v === "boolean"
91	    );
92	    if (allPrimitive) {
93	      const inline = `[${value.map((v) => emitValue(v, 0)).join(", ")}]`;
94	      if (inline.length <= 72) return inline;
95	    }
96	    const items = value.map((v) => `${padInner}${emitValue(v, indent + 1)}`);
97	    return `[\n${items.join(",\n")},\n${pad}]`;
98	  }
99	  if (typeof value === "object") {
100	    if (
101	      "__tsExpression" in value &&
102	      typeof (value as TsExpression).__tsExpression === "string"
103	    ) {
104	      return (value as TsExpression).__tsExpression;
105	    }
106	    const entries = Object.entries(value as Record<string, unknown>);
107	    if (entries.length === 0) return "{}";
108	    const lines = entries.map(
