124	 * line at `indent`+1). `fields` are pre-rendered `key: value` strings; empty
125	 * entries are dropped so omitted/default fields never appear.
126	 */
127	function objectLiteral(fields: string[], indent = 0): string {
128	  const pad = "  ".repeat(indent);
129	  const padInner = "  ".repeat(indent + 1);
130	  const present = fields.filter((f) => f.length > 0);
131	  if (present.length === 0) return "{}";
132	  return `{\n${present.map((f) => `${padInner}${f}`).join(",\n")},\n${pad}}`;
133	}
