1	/**
2	 * `pi-review` is a required status check and `enforce_admins` is on, so a
3	 * non-empty `blockers` array is unbypassable — review.sh turns `blockers>0`
4	 * into a red status with no override path.
5	 *
6	 * That makes one prompt sentence load-bearing for the whole repo. #2306 hit
7	 * it: the reviewer runs under `codex exec --sandbox read-only`, the changed
8	 * test called `mkdtemp`, the write failed with EPERM, and §4 told the
9	 * reviewer to "record that as a `blocker`" — so a property of the reviewer's
10	 * own sandbox, not of the diff, blocked main. A re-run with byte-identical
11	 * content then passed, which is what a gate that measures the environment
12	 * looks like from the outside.
13	 *
14	 * Three other sections (§2, §6, and the Blockers list) already say the
15	 * opposite: environment problems are `[env]` notes and blockers require a
16	 * failure the diff caused. This pins that the prompt says it in ONE
17	 * direction, matching the *shape* of the rule rather than its wording — an
18	 * exact-string assertion would fail on any honest rewrite while still letting
19	 * a freshly-worded contradiction through.
20	 *
21	 * The fixtures below are the point of the file. Three revisions of this guard
22	 * were wrong in three different ways, each one passing against a prompt that
23	 * contradicted itself, so the guard is tested against known-bad and known-good
24	 * phrasings rather than trusted to be correct by inspection.
25	 */
26	
27	import { readFileSync } from "node:fs";
28	import { join, resolve } from "node:path";
29	import { describe, expect, it } from "bun:test";
30	
31	const REPO_ROOT = resolve(import.meta.dir, "..", "..");
32	const PROMPT = join(REPO_ROOT, "prompts/review-prompt.md");
33	
34	/** Reviewer-side inability to execute — a fact about the sandbox, not the diff. */
35	const ENV_INABILITY =
36	  /(environment (itself )?is broken|reviewer's environment|sandbox|read-only|EPERM|execution is unavailable|denies the writes|cannot run|can't run|unable to run|could not run)/i;
37	const MENTIONS_BLOCKER = /blocker/i;
38	const CLAUSE_BOUNDARY = /(?<=[.;!?—,])\s*/;
39	
40	/**
41	 * The two ways the prompt may legitimately connect an env failure to
42	 * blockers. Anything else inside an env rule is a contradiction.
43	 *
44	 * This is a whitelist because the three revisions before it were blacklists —
45	 * "does this clause contain a negation" — and each died to a negation that
46	 * governed a different verb: first across sentences ("Do not retry
47	 * indefinitely"), then across a semicolon, then across an "and" ("do not hide
48	 * it and record it as a blocker"). Which verb a `not` attaches to is not
49	 * something a regex settles, and every patch moved the counter-example one
50	 * conjunction further out.
51	 *
52	 * Inverting it removes the question. A phrasing this does not recognize gets
53	 * flagged rather than allowed, so an unanticipated rewrite fails loudly on a
54	 * 250-line document instead of silently reopening an unbypassable gate.
55	 */
56	const PROHIBITS_BLOCKER = [
57	  /\b(?:never|not)\s+a\s+`?blockers?`?/i,
58	  /\bnot\s+\w+\s+(?:them\s+)?(?:to|under|in|as)\s+`?blockers?`?/i,
59	];
60	
61	/**
62	 * Every clause that ties a reviewer-side inability to `blockers` without
63	 * prohibiting it. Empty means the prompt states the rule in one direction.
64	 */
65	function contradictions(markdown: string): string[] {
66	  return bullets(markdown)
67	    .filter((bullet) => ENV_INABILITY.test(bullet))
68	    .flatMap((bullet) => bullet.split(CLAUSE_BOUNDARY))
69	    .filter((clause) => MENTIONS_BLOCKER.test(clause))
70	    .filter(
71	      (clause) => !PROHIBITS_BLOCKER.some((allowed) => allowed.test(clause))
72	    )
73	    .map((clause) => clause.trim());
74	}
75	
76	/**
77	 * Markdown bullets, joined with their indented continuation lines — the rule
78	 * that broke #2306 spanned three lines, so a line-at-a-time scan misses it.
79	 */
80	function bullets(markdown: string): string[] {
81	  const out: string[] = [];
82	  let current: string | null = null;
83	  for (const line of markdown.split("\n")) {
84	    if (/^- /.test(line)) {
85	      if (current !== null) out.push(current);
86	      current = line;
87	    } else if (current !== null && /^\s+\S/.test(line)) {
88	      current += ` ${line.trim()}`;
89	    } else {
90	      if (current !== null) out.push(current);
91	      current = null;
92	    }
93	  }
94	  if (current !== null) out.push(current);
95	  return out;
96	}
97	
98	/** Phrasings that must be flagged. Each one defeated an earlier revision. */
99	const CONTRADICTORY = [
100	  // The literal §4 rule that red-flagged #2306 twice.
101	  "- If the environment itself is broken (e.g. you cannot run even a narrow\n  test file), record that as a `blocker` and finish with a partial verdict.",
102	  // Added alongside a correct rule instead of replacing it — the realistic
103	  // drift, and what an exact-string guard misses entirely.
104	  "- When your sandbox denies the writes a narrow test needs, list that under\n  `blockers` so the gap stays visible to the merger.",
105	  // An unrelated negation earlier in the same sentence; defeats a
106	  // sentence-scoped negation search.
107	  "- If your sandbox is read-only, do not hide it; record it as a blocker.",
108	  // The same, with `and` instead of `;` — no clause boundary at all, which is
109	  // what defeated the clause-scoped revision.
110	  "- If your sandbox is read-only, do not hide it and record it as a blocker.",
111	  // Bare copula, no imperative verb to key on.
112	  "- A read-only sandbox counts as a `blocker`.",
113	  // Negation present but attached to something else entirely.
114	  "- When the reviewer's environment fails, nothing stops you recording a blocker.",
115	  // A verb the whitelist was never written around.
116	  "- If you cannot run the suite, escalate it to `blockers`.",
117	];
118	
119	/** Phrasings that must NOT be flagged, so the guard stays usable. */
120	const CONSISTENT = [
