/**
 * `make review-fix` is step 5 of AGENTS.md "Ship a change", but unlike
 * `make review` it posts no status — so when its CLI is unavailable the step
 * just doesn't happen, and nothing anywhere records that a quality pass was
 * skipped. It was hard-wired to codex (`command -v codex || exit 1`) while
 * `review.sh` already honoured `REVIEWER_CLI=auto|codex|claude`, so a codex
 * quota outage removed the fixer entirely with no way to ask for the other CLI.
 *
 * These exercise the real shell functions rather than asserting on the script
 * text, and pin the structural half — that `review-fix.sh` reaches its CLI
 * through the shared selector — because that is the property that regressed.
 */

import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { describe, expect, it } from "bun:test";

const REPO_ROOT = resolve(import.meta.dir, "..", "..");
const REVIEWER_LIB = join(REPO_ROOT, "scripts/lib/review-reviewer.sh");
const REVIEW_FIX = join(REPO_ROOT, "scripts/review-fix.sh");

/** Run one selector call in a subshell and return stdout/stderr/status. */
function selector(
  call: string,
  env: Record<string, string> = {}
): { stdout: string; stderr: string; status: number | null } {
  const result = spawnSync(
    "bash",
    ["-c", `set -euo pipefail; . "${REVIEWER_LIB}"; ${call}`],
    { encoding: "utf8", env: { ...process.env, ...env } }
  );
  return {
    stdout: result.stdout.trim(),
    stderr: result.stderr.trim(),
    status: result.status,
  };
}

describe("reviewer selection is shared by review.sh and review-fix.sh", () => {
  it("honours an explicit codex or claude choice", () => {
    expect(selector('review_select_reviewer codex').stdout).toBe("codex");
    expect(selector('review_select_reviewer claude').stdout).toBe("claude");
  });

  it("picks the other CLI under auto so a reviewer never reviews itself", () => {
    // Outside a codex harness `auto` means codex; inside one it flips to
    // claude. The flip is the whole point of `auto` — an agent grading its own
    // diff with its own model is not an independent review.
    expect(selector('review_select_reviewer auto', { CODEX_THREAD_ID: "" }).stdout).toBe(
      "codex"
    );
    expect(
      selector('review_select_reviewer auto', { CODEX_THREAD_ID: "t_123" }).stdout
    ).toBe("claude");
  });

  it("rejects an unknown REVIEWER_CLI instead of falling back", () => {
    const result = selector('review_select_reviewer sonnet');
    expect(result.status).not.toBe(0);
    expect(result.stderr).toContain("invalid REVIEWER_CLI=sonnet");
  });

  it("keeps the review model off the weaker tiers", () => {
    expect(selector('review_validate_claude_model fable').status).toBe(0);
    expect(selector('review_validate_claude_model opus').status).toBe(0);
    const rejected = selector('review_validate_claude_model claude-sonnet-5');
    expect(rejected.status).not.toBe(0);
    expect(rejected.stderr).toContain("invalid CLAUDE_REVIEW_MODEL");
  });
});

describe("review-fix.sh routes through the shared selector", () => {
  const script = readFileSync(REVIEW_FIX, "utf8");

  it("sources the shared reviewer lib", () => {
    expect(script).toContain("lib/review-reviewer.sh");
    expect(script).toMatch(/review_select_reviewer/);
  });

  it("has an invocation arm for both CLIs", () => {
    // The regression was a single hard-coded `codex exec`. Requiring both
    // names to appear as invocations catches a future edit that drops one arm
    // while leaving the selector call in place.
    expect(script).toMatch(/codex exec/);
    expect(script).toMatch(/claude -p/);
  });

  it("gives the fixer the write tools that make it a fixer", () => {
    // A fixer pass without Edit/Write silently degrades to a review whose
    // findings go nowhere — the tree comes back clean and reads as "no
    // findings", which is indistinguishable from a healthy run.
    expect(script).toMatch(/--tools [^\n]*Edit[^\n]*Write/);
  });

  it("does not gate every run on codex being installed", () => {
    expect(script).not.toMatch(/command -v codex >\/dev\/null 2>&1 \|\|/);
  });
});

