1	/**
2	 * `prompts/review-output-schema.json` is handed to BOTH reviewer CLIs by
3	 * `scripts/review.sh` — `claude --json-schema "$(cat …)"` and `codex exec
4	 * --output-schema …`. The two accept overlapping but not identical dialects,
5	 * and `review.sh` fails closed: a schema either CLI rejects produces no
6	 * verdict, `finalize_review_status error`, and a red `pi-review` status. That
7	 * check is required with `enforce_admins` on, so a one-key schema edit can
8	 * block every merge in the repo.
9	 *
10	 * That is exactly what happened. The file opened with
11	 *
12	 *   "$schema": "https://json-schema.org/draft/2020-12/schema"
13	 *
14	 * and `claude --json-schema` cannot resolve that meta-schema reference:
15	 *
16	 *   Error: --json-schema is not a valid JSON Schema: no schema with key or
17	 *   ref "https://json-schema.org/draft/2020-12/schema"
18	 *
19	 * It exits before reading the prompt, so the failure looks like a dead
20	 * reviewer rather than a bad key. codex accepts the file either way, so the
21	 * repo ran for as long as codex was the selected reviewer and only broke on
22	 * the fallback — the worst shape for a gate, because it is discovered under a
23	 * quota outage when there is no second reviewer to fall back to.
24	 *
25	 * The keys asserted here are the ones whose absence a reviewer only reports
26	 * as "no schema-valid JSON verdict", which reads as a model failure and sends
27	 * the next person to re-run the review instead of to this file.
28	 */
29	
30	import { readFileSync } from "node:fs";
31	import { join, resolve } from "node:path";
32	import { describe, expect, it } from "bun:test";
33	
34	const REPO_ROOT = resolve(import.meta.dir, "..", "..");
35	const SCHEMA_FILE = join(REPO_ROOT, "prompts/review-output-schema.json");
36	
37	/**
38	 * `$schema` and `$id` point the loader at a document it will not fetch —
39	 * claude refuses the file outright with "no schema with key or ref …". Local
40	 * `$defs`/`$ref` DO load in the claude CLI (verified: a `#/$defs/…` schema
41	 * round-trips), but they are reference machinery a flat verdict schema does
42	 * not need, so the guard keeps the file reference-free instead of tracking
43	 * which CLI tolerates which indirection.
44	 */
45	function unsupportedKeys(schema: Record<string, unknown>): string[] {
46	  return ["$schema", "$id", "$ref", "$defs"].filter((key) => key in schema);
47	}
48	
49	/**
50	 * `required` naming a property that does not exist is the other way this file
51	 * fails closed: codex's structured-output mode rejects the schema, and the
52	 * error surfaces as an empty verdict rather than as a schema complaint.
53	 */
54	function danglingRequired(schema: {
55	  required?: string[];
56	  properties?: Record<string, unknown>;
57	}): string[] {
58	  const properties = schema.properties ?? {};
59	  return (schema.required ?? []).filter((name) => !(name in properties));
60	}
61	
62	describe("review output schema stays loadable by both reviewer CLIs", () => {
63	  const raw = readFileSync(SCHEMA_FILE, "utf8");
64	  const schema = JSON.parse(raw) as Record<string, any>;
65	
66	  it("stays reference-free so both reviewer CLIs load it", () => {
67	    expect(unsupportedKeys(schema)).toEqual([]);
68	  });
69	
70	  it("flags the draft-2020-12 declaration that broke the claude reviewer", () => {
71	    expect(
72	      unsupportedKeys({
73	        $schema: "https://json-schema.org/draft/2020-12/schema",
74	        type: "object",
75	      })
76	    ).toEqual(["$schema"]);
77	  });
78	
79	  it("requires only properties it defines", () => {
80	    expect(danglingRequired(schema)).toEqual([]);
81	  });
82	
83	  it("flags a required name with no matching property", () => {
84	    expect(
85	      danglingRequired({
86	        required: ["bugs", "typo_field"],
87	        properties: { bugs: { type: "number" } },
88	      })
89	    ).toEqual(["typo_field"]);
90	  });
91	
92	  it("keeps the closed-object shape codex's structured output needs", () => {
93	    expect(schema.type).toBe("object");
94	    expect(schema.additionalProperties).toBe(false);
95	  });
96	
97	  it("still carries the fields review.sh reads out of the verdict", () => {
98	    // review.sh pipes the verdict through `jq -r .<field>` and validates each
99	    // one before posting the status; a field dropped here fails the gate for
100	    // every PR, not just the one that dropped it.
101	    for (const field of [
102	      "bug_free_confidence",
103	      "bugs",
104	      "slop",
105	      "simplicity",
106	      "blockers",
107	      "change_type",
108	      "behavior_change_risk",
109	      "tests_adequate",
110	      "suggested_fixes",
111	      "notes",
112	      "categories",
113	    ]) {
114	      expect(schema.required).toContain(field);
115	    }
116	  });
117	});

