60	 * Drop chat-link style triggers when cloning a Behavior onto an entity.
61	 * Steer + reply_to_source on message.created is the live channel responder
62	 * contract; copying it would double-reply in linked channels.
63	 */
64	function stripChatLinkTriggers(triggers: unknown): unknown {
65	  if (!Array.isArray(triggers)) return triggers ?? [];
66	  return triggers.filter((candidate) => {
67	    if (!candidate || typeof candidate !== 'object') return true;
68	    const t = candidate as Record<string, unknown>;
69	    if (t.kind !== 'event') return true;
70	    const eventTypes = t.event_types;
71	    if (!Array.isArray(eventTypes) || !eventTypes.includes('message.created')) {
72	      return true;
73	    }
74	    if (t.active_run === 'steer' && t.output === 'reply_to_source') {
75	      return false;
76	    }
77	    return true;
78	  });
79	}
