85	export async function handleCreate(
86	  args: ManageBehaviorsArgs,
87	  _env: Env,
88	  ctx: ToolContext
89	): Promise<{
90	  action: 'create';
91	  behavior_id: string;
92	  version: number;
93	  status: string;
94	  sources?: Array<{ name: string; query: string }>;
95	  view_url?: string;
96	}> {
97	  const sql = getDb();
98	
99	  // Require slug for create. Instruction text (prompt) is required only when
100	  // the trigger shape runs on instructions alone — event-turn Behaviors may
101	  // omit it and run on the built-in default (see assertBehaviorInstructions,
102	  // called after triggers resolve below). The output contract is not authored
103	  // here: an entity-typed watcher (keying_config.entity_type) derives it from
104	  // entity_types.metadata_schema at runtime, and an untyped watcher uses the
105	  // worker's free-form summary fallback.
106	  if (!args.slug) {
107	    throw new ToolUserError('slug is required for create action');
108	  }
109	  if (!args.agent_id) {
110	    throw new ToolUserError(
111	      'agent_id is required to create a Behavior (the agent that executes it).'
112	    );
113	  }
114	  assertValidExecutionConfig(args.execution_config, ctx);
115	  // A device pin runs the watcher's agent CLI on the device owner's machine —
116	  // validate the caller may target this device (own it, or org owner/admin
117	  // over a device attached to the org) before storing it.
118	  await assertDeviceWorkerAccess(sql, args.device_worker_id, ctx);
119	
120	  // entity_id is optional: omit it for an org-scoped/global watcher.
121	  const entityId = args.entity_id;
122	
123	  // Parse JSON inputs
124	  const keyingConfig = parseJsonInput<Record<string, unknown>>(args.keying_config, 'keying_config');
125	  const classifiers = parseJsonInput<unknown[]>(args.classifiers, 'classifiers');
126	
127	  // Build sources array. Sources are authored two ways and merged here:
128	  //   1. `@`-mention tokens in the prompt (the owletto composer's primary path)
129	  //      — the backend derives them so the UI sends only the raw prompt.
130	  //   2. explicit `args.sources` (API callers / legacy).
131	  // If neither yields anything, fall back to a default all-events source.
132	  // `create_version` deliberately does NOT derive (see version-actions.ts):
133	  // an existing prompt's prose must not silently re-author the Behavior's
134	  // source set during an otherwise unrelated version bump.
135	  const promptSources = extractSourcesFromPromptTokens(args.prompt ?? '');
136	  const explicitSources = args.sources ?? [];
137	  const merged = mergePromptSources(explicitSources, promptSources);
138	  const sources: Array<{ name: string; query: string }> =
139	    merged.length > 0
140	      ? merged
141	      : [
142	          {
143	            name: 'content',
144	            query: DEFAULT_BEHAVIOR_SOURCE_QUERY,
145	          },
146	        ];
147	
148	  // Validate watcher config
149	  assertWatcherVersionConfigValid({
150	    prompt: args.prompt,
151	    classifiers,
152	    sources,
153	  });
154	
155	  if (!args.agent_id) {
156	    // The scheduler joins on `agent_id IS NOT NULL` (see
157	    // packages/server/src/watchers/automation.ts:469), so a watcher without
158	    // an agent has no way to execute. Schema-wise `agent_id` is `Type.Optional`
159	    // because the field is shared across all manage_behaviors actions, but
160	    // create enforces it: a watcher with no owning agent is a zombie row.
161	    throw new ToolUserError(
162	      'agent_id is required to create a Behavior (the agent that executes it).'
163	    );
164	  }
