94	  const prompt = args.prompt ?? (prev.prompt as string);
95	  // Sources on a version bump — full-replacement semantics keyed on INTENT,
96	  // distinguishing "the caller omitted sources" (inherit) from "the caller
97	  // explicitly set them" (replace, even to empty). This closes #2048: passing
98	  // `sources: []` used to be conflated with "omitted" and silently re-inherited
