23	// ============================================
24	// Types
25	// ============================================
26	
27	export interface WatcherOperationResult {
28	  behavior_id: string;
29	  success: boolean;
30	  message: string;
31	  version?: number;
32	}
33	
34	type WatcherAccessMode = 'read' | 'write';
