41	
42	// ============================================
43	// JSON coercion helpers
44	// ============================================
45	
46	/**
47	 * Coerce a maybe-stringified JSON value into a parsed value. One helper, three
48	 * failure policies:
49	 *  - `keep`        — non-string passes through; bad string returns the raw string.
50	 *  - `throw`       — `null`/`undefined` → `undefined`; bad string throws `${label} must be valid JSON: …`.
51	 *  - `{ fallback }` — `null`/`undefined` or bad string → the supplied fallback.
52	 * `requireObject` (with `parseError`/`shapeError` messages) additionally rejects
53	 * non-object / array results — used for `extracted_data`.
54	 */
55	function coerceJson(value: unknown, opts: { onError: 'keep' }): unknown;
56	function coerceJson<T>(value: unknown, opts: { onError: 'throw'; label: string }): T | undefined;
57	function coerceJson<T>(value: unknown, opts: { onError: { fallback: T } }): T;
58	function coerceJson(
59	  value: unknown,
60	  opts: { requireObject: { parseError: string; shapeError: string } }
61	): Record<string, unknown>;
62	function coerceJson(
63	  value: unknown,
64	  opts: {
65	    onError?: 'keep' | 'throw' | { fallback: unknown };
66	    label?: string;
67	    requireObject?: { parseError: string; shapeError: string };
68	  }
69	): unknown {
70	  let parsed: unknown;
71	  if (typeof value === 'string') {
72	    try {
73	      parsed = JSON.parse(value);
74	    } catch (error) {
75	      if (opts.requireObject) throw new Error(opts.requireObject.parseError);
76	      if (opts.onError === 'keep') return value;
77	      if (opts.onError === 'throw') {
78	        throw new Error(`${opts.label} must be valid JSON: ${getErrorMessage(error)}`);
79	      }
80	      if (opts.onError) return opts.onError.fallback;
81	      throw error;
82	    }
83	  } else if (value === undefined || value === null) {
84	    if (opts.requireObject) {
85	      // fall through to the shape check below
86	    } else if (opts.onError === 'throw') {
87	      return undefined;
88	    } else if (opts.onError && opts.onError !== 'keep') {
89	      return opts.onError.fallback;
90	    }
91	    parsed = value;
92	  } else {
93	    parsed = value;
94	  }
95	
96	  if (opts.requireObject) {
97	    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
98	      throw new Error(opts.requireObject.shapeError);
99	    }
100	  }
101	  return parsed;
102	}
103	
104	export function parseJson(value: unknown): any {
105	  return coerceJson(value, { onError: 'keep' });
106	}
107	
108	export function normalizeExtractedData(value: unknown): Record<string, unknown> {
109	  return coerceJson(value, {
110	    requireObject: {
111	      parseError: 'extracted_data must be a valid JSON object. Received an invalid JSON string.',
112	      shapeError:
113	        "extracted_data must be a JSON object matching the Behavior's extraction contract.",
114	    },
115	  });
116	}
117	
118	export function parseJsonInput<T>(value: unknown, label: string): T | undefined {
119	  return coerceJson<T>(value, { onError: 'throw', label });
120	}
121	
122	export function normalizeStoredJsonField<T>(value: unknown, fallback: T): T {
123	  return coerceJson<T>(value, { onError: { fallback } });
124	}
125	
126	export function toJsonParam(sql: DbClient, value: unknown): unknown {
127	  if (value === undefined || value === null) return null;
128	  return sql.json(value);
129	}
130	
131	export function toTextArrayParam(values: string[]): string {
132	  // Same trim/drop-empty/dedupe as the review's proposedAfter (one core helper),
133	  // so displayed tags == stored tags.
134	  const arr = normalizeBehaviorTags(values);
135	  if (arr.length === 0) return '{}';
136	  return (
137	    '{' + arr.map((v) => '"' + v.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"').join(',') + '}'
138	  );
139	}
