150	// ============================================
151	// Watcher config validation
152	// ============================================
153	
154	function validateWatcherConfig(input: {
155	  prompt?: string;
156	  classifiers?: unknown[];
157	  sources?: Array<{ name: string; query: string }>;
158	}): string | null {
159	  // Instruction PRESENCE is trigger-shape-dependent (event-turn Behaviors may
