/**
 * LobuRef — one portable, typed reference to any first-class object the UI can
 * point at: an entity, connection, connector, feed, watcher, member, or event.
 * The reference picker emits these, and the chat composer serializes them into
 * a message so an agent turn can be told "this is about <that object>".
 *
 * Inline wire form (rides inside an ordinary message `content` string — no new
 * API field):
 *
 *   @[entity:Spotify](/acme/company/spotify)
 *   @[connection:Stripe prod](/acme/connectors/stripe/42)
 *
 * `kind`  — object family (drives worker-side expansion).
 * `id`    — stable id as a string (entity id, connection id, watcher uuid,
 *           connector key, member user id, event id).
 * `path`  — frontend route to the object; makes the chip clickable and lets the
 *           ref be re-resolved (entities via resolve_path, others via their API).
 * `label` — display name captured at pick time (what the chip shows).
 */

export type LobuRefKind =
	| "entity"
	| "connection"
	| "connector"
	| "feed"
	| "behavior"
	| "member"
	| "metric"
	| "sql"
	| "event";

export const LOBU_REF_KINDS: readonly LobuRefKind[] = [
	"entity",
	"connection",
	"connector",
	"feed",
	"behavior",
	"member",
	"metric",
	"sql",
	"event",
] as const;

export interface LobuRef {
	kind: LobuRefKind;
	id: string;
	path: string;
	label: string;
}

interface BehaviorSource {
	name: string;
	query: string;
}

function isLobuRefKind(value: string): value is LobuRefKind {
	return (LOBU_REF_KINDS as readonly string[]).includes(value);
}

/** One inline ref token: `@[kind:id:label](path)`. Groups: kind, id, label,
 *  path. id = any char except `:`/`]` (a controlled slug); label = any char
 *  except `]`; path = any char except `)` / whitespace (0+, so an empty `()` is
 *  valid — a synthetic SQL action carries no path). Embedding the id lets
 *  callers recover the object's stable identifier (e.g. a feed_key or
 *  `type.measure`) from the token alone — needed to compile watcher sources.
 *
 *  This grammar is mirrored by the server in `watchers/source-refs.ts`, which
 *  the owletto submodule cannot import. Keep both copies in sync. */
const REF_TOKEN = /@\[([a-z]+):([^:\]]*):([^\]]*)\]\(([^)\s]*)\)/g;

/** Serialize one ref to its inline token. Brackets/colons are stripped from the
 *  label so the token stays unambiguous. */
export function serializeRef(ref: LobuRef): string {
	const safeLabel = ref.label.replace(/[[\]]/g, "").trim();
	const safeId = ref.id.replace(/[[\]:]/g, "");
	return `@[${ref.kind}:${safeId}:${safeLabel}](${ref.path})`;
}

/**
 * SQL is the one kind with no first-class object to point at — the query is
 * authored inline and lives nowhere but the token itself. So a `sql` ref carries
 * its whole query in the `path` slot, URL-encoded behind a `#sql=` marker.
 * Encoding turns spaces/parens/newlines into `%xx`, so the token's `path` group
 * (no space, no `)`) stays satisfied and the query survives the round-trip
 * verbatim. The `#` marks the path as a payload, not a route — so chip/pill
 * click opens the edit dialog instead of navigating.
 */
const SQL_PATH_PREFIX = "#sql=";

/** `encodeURIComponent` leaves `( ) ' ! * ~` unescaped, but the token's path
 *  group forbids `)` (it closes the `(...)`) — so we additionally percent-encode
 *  those sub-delims. `decodeURIComponent` reverses all of it. */
function encodeSqlPayload(query: string): string {
	return encodeURIComponent(query).replace(
		/[()'!*~]/g,
		(c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`,
	);
}

/** Build the `path` for a `sql` ref: `#sql=<urlencoded query>`. */
export function sqlRefPath(query: string): string {
	return `${SQL_PATH_PREFIX}${encodeSqlPayload(query)}`;
}

/** Recover the raw query from a `sql` ref's `path`, or null if it isn't one. */
export function sqlQueryFromPath(path: string): string | null {
	if (!path.startsWith(SQL_PATH_PREFIX)) return null;
	try {
		return decodeURIComponent(path.slice(SQL_PATH_PREFIX.length));
	} catch {
		return null;
	}
}

/** True if a path is a SQL payload rather than a navigable route. */
export function isSqlRefPath(path: string): boolean {
	return path.startsWith(SQL_PATH_PREFIX);
}

/**
 * Parse every ref token out of a text body, in order. Unknown kinds are skipped
 * rather than thrown, so arbitrary user text containing `@[...]` never breaks
 * send.
 */
export function parseRefs(text: string): LobuRef[] {
	const out: LobuRef[] = [];
	for (const m of text.matchAll(REF_TOKEN)) {
		const [, kind, id, label, path] = m;
		if (!kind || !isLobuRefKind(kind) || !path) continue;
		out.push({ kind, id: id ?? "", label: (label ?? "").trim(), path });
	}
	return out;
}

const SOURCE_KIND_TO_MODE: Record<string, string> = {
	feed: "feed",
	connection: "connection",
	connector: "connector",
	channel: "channel",
	metric: "metric",
};

function sourceName(value: string): string {
	return (
		value
			.trim()
			.toLowerCase()
			.replace(/[^a-z0-9_]+/g, "_")
			.replace(/^_+|_+$/g, "") || "source"
	);
}

/**
 * Append `{name, query}` to `sources` unless the query is already present,
 * uniquifying the derived name with a numeric suffix. Shared by the chip codec
 * and the Behavior sources editor so both name and dedupe identically.
 */
function appendBehaviorSource(
	sources: BehaviorSource[],
	seenQueries: Set<string>,
	usedNames: Set<string>,
	label: string,
	fallback: string,
	query: string,
): void {
	const normalizedQuery = query.trim();
	if (!normalizedQuery || seenQueries.has(normalizedQuery)) return;
	seenQueries.add(normalizedQuery);
	let name = sourceName(label || fallback);
	if (usedNames.has(name)) {
		let suffix = 2;
		while (usedNames.has(`${name}_${suffix}`)) suffix += 1;
		name = `${name}_${suffix}`;
	}
	usedNames.add(name);
	sources.push({ name, query: normalizedQuery });
}

/**
 * The source a single reference stands for, appended to `existing`. Returns
 * `existing` unchanged when the ref carries no query or already appears — the
 * caller can compare lengths to tell whether anything was added.
 */
export function behaviorSourcesWithRef(
	ref: LobuRef,
	existing: BehaviorSource[],
): BehaviorSource[] {
	const sources = [...existing];
	const seenQueries = new Set(existing.map((source) => source.query.trim()));
	const usedNames = new Set(existing.map((source) => source.name));
	if (ref.kind === "sql") {
		const query = sqlQueryFromPath(ref.path);
		if (query) {
			appendBehaviorSource(
				sources,
				seenQueries,
				usedNames,
				ref.label,
				"sql_source",
				query,
			);
		}
		return sources;
	}
	const mode = SOURCE_KIND_TO_MODE[ref.kind];
	const value = ref.id.trim();
	if (mode && value) {
		appendBehaviorSource(
			sources,
			seenQueries,
			usedNames,
			ref.label,
			value,
			`@${mode}:${value}`,
		);
	}
	return sources;
}

/**
 * Derive the source replacement represented by the composer's reference chips.
 * Keep this in sync with the server's create-time prompt derivation.
 */
export function behaviorSourcesFromPrompt(
	text: string,
	explicit: BehaviorSource[] = [],
): BehaviorSource[] {
	const sources = [...explicit];
	const seenQueries = new Set(explicit.map((source) => source.query.trim()));
	const usedNames = new Set(explicit.map((source) => source.name));

	const push = (label: string, fallback: string, query: string) =>
		appendBehaviorSource(
			sources,
			seenQueries,
			usedNames,
			label,
			fallback,
			query,
		);

	for (const match of text.matchAll(REF_TOKEN)) {
		const [, kind, id, label, path] = match;
		if (!kind) continue;
		if (kind === "sql") {
			const query = sqlQueryFromPath(path ?? "");
			if (query) push(label ?? "", "sql_source", query);
			continue;
		}
		const mode = SOURCE_KIND_TO_MODE[kind];
		const value = (id ?? "").trim();
		if (mode && value) push(label ?? "", value, `@${mode}:${value}`);
	}

	return sources;
}

/** A segment of a tokenized body: a verbatim text run or a ref token. */
export type RefSegment =
	| { type: "text"; text: string }
	| { type: "ref"; ref: LobuRef };

/**
 * Split a body into ordered segments — plain text runs interleaved with ref
 * tokens. Pure and allocation-light: used to render sent messages (a stateless
 * pass over the string, no editor instance), so a `@[kind:label](path)` token
 * becomes a pill and everything else stays as text. Unknown kinds pass through
 * as text.
 */
export function tokenizeRefs(text: string): RefSegment[] {
	const segments: RefSegment[] = [];
	let last = 0;
	const re = new RegExp(REF_TOKEN.source, "g");
	let m: RegExpExecArray | null = re.exec(text);
	while (m !== null) {
		const [raw, kind, id, label, path] = m;
		const idx = m.index;
		if (kind && isLobuRefKind(kind) && path) {
			if (idx > last)
				segments.push({ type: "text", text: text.slice(last, idx) });
			segments.push({
				type: "ref",
				ref: { kind, id: id ?? "", label: (label ?? "").trim(), path },
			});
			last = idx + raw.length;
		}
		m = re.exec(text);
	}
	if (last < text.length)
		segments.push({ type: "text", text: text.slice(last) });
	return segments;
}

/** True if the text contains at least one ref token. Uses a fresh, non-global
 *  regex so the shared `REF_TOKEN`'s `lastIndex` is never left dirty — otherwise
 *  a `hasRefs(x) && parseRefs(x)` pairing would skip the first token (matchAll
 *  clones the source regex's lastIndex). */
export function hasRefs(text: string): boolean {
	return new RegExp(REF_TOKEN.source).test(text);
}

/**
 * Replace every ref token with a plain-text rendering, for surfaces that can't
 * show chips (defaults to the label).
 */
export function stripRefs(
	text: string,
	render: (ref: LobuRef) => string = (r) => r.label,
): string {
	return text.replace(
		REF_TOKEN,
		(full, kind: string, id: string, label: string, path: string) => {
			if (!isLobuRefKind(kind)) return full;
			return render({ kind, id: id ?? "", label: (label ?? "").trim(), path });
		},
	);
}

