/**
 * Behavior instruction compile — the web mirror of `lobu apply`.
 *
 * A Behavior has no author-facing prompt (issue #2320). Instructions are the
 * ordered skill bodies of the owning agent, joined at save time and frozen into
 * the version. The server never sees `skills[]` — it stores only the compiled
 * text — so this module and the CLI's `compileBehaviorInstructions`
 * (`packages/cli/src/commands/_lib/apply/desired-state.ts`) must agree
 * byte-for-byte, or the same Behavior authored in the two surfaces would freeze
 * different instructions and churn versions against each other.
 *
 * The freeze is the honest part of the model: editing a skill afterwards does
 * NOT change an existing Behavior until it is saved again (an accepted limit in
 * #2320). Copy in the picker says so rather than implying a live link.
 */

/** Max skills a Behavior may reference. Mirrors `MAX_BEHAVIOR_SKILLS` (CLI). */
export const MAX_BEHAVIOR_SKILLS = 5;

/** Compiled-instruction ceiling. Mirrors `MAX_COMPILED_INSTRUCTIONS_BYTES`. */
export const MAX_COMPILED_INSTRUCTIONS_BYTES = 32 * 1024;

/** A skill the picker can offer: a library entry with a usable body. */
export interface BehaviorSkillOption {
	name: string;
	description?: string;
	/**
	 * Authored body. Custom skills carry `content`; bundled/system skills carry
	 * the catalog's `instructions`. The CLI only ever resolves files into
	 * `content`, so it has no equivalent fallback.
	 */
	content?: string;
	instructions?: string;
	enabled: boolean;
}

/** The body a skill contributes to the compile, or "" when it has none. */
export function skillBody(skill: BehaviorSkillOption): string {
	return (skill.content ?? skill.instructions ?? "").trim();
}

/** Skills that can actually be compiled: enabled and carrying a body. */
export function selectableSkills(
	library: BehaviorSkillOption[],
): BehaviorSkillOption[] {
	return library.filter((skill) => skill.enabled && skillBody(skill) !== "");
}

/** Trigger shape this module needs. Extra keys are ignored. */
export interface BehaviorTriggerLike {
	kind?: string;
	execution?: string;
}

/**
 * Whether the Behavior runs on its compiled instructions alone.
 *
 * An event trigger executing as "turn" carries its own content (the incoming
 * message/event) and may run with zero skills on the built-in default.
 * Everything else — schedule triggers, event triggers with execution "window",
 * and Behaviors with no triggers at all (manual runs) — has nothing but its
 * instructions, so it needs at least one skill. Mirrors `assertBehaviorSkills`.
 */
export function behaviorRequiresSkills(
	triggers: BehaviorTriggerLike[] | undefined,
): boolean {
	const list = triggers ?? [];
	if (list.length === 0) return true;
	return list.some(
		(trigger) => trigger.kind === "schedule" || trigger.execution === "window",
	);
}

/**
 * Join the selected skill bodies in order. Returns "" for an empty selection —
 * the event-turn case, where the server applies its built-in default.
 */
export function compileBehaviorInstructions(
	selected: string[],
	library: BehaviorSkillOption[],
): string {
	if (selected.length === 0) return "";
	const byName = new Map(library.map((skill) => [skill.name, skill]));
	const bodies: string[] = [];
	for (const name of selected) {
		const skill = byName.get(name);
		const body = skill ? skillBody(skill) : "";
		if (body) bodies.push(body);
	}
	return bodies.join("\n\n");
}

/** UTF-8 byte length of the compiled text (the cap is bytes, not characters). */
export function compiledByteLength(compiled: string): number {
	return new TextEncoder().encode(compiled).length;
}

/**
 * Validate a selection against the same rules `lobu apply` enforces, so the web
 * cannot author a Behavior the CLI would reject. Returns null when valid.
 */
export function validateBehaviorSkills(
	selected: string[],
	library: BehaviorSkillOption[],
	triggers: BehaviorTriggerLike[] | undefined,
): string | null {
	const duplicates = selected.filter((name, i) => selected.indexOf(name) !== i);
	if (duplicates.length > 0) {
		return `Duplicate skill: ${[...new Set(duplicates)].join(", ")} — the compile is ordered, so each skill may appear once.`;
	}
	if (selected.length > MAX_BEHAVIOR_SKILLS) {
		return `${selected.length} skills selected — the maximum is ${MAX_BEHAVIOR_SKILLS}.`;
	}
	const byName = new Map(library.map((skill) => [skill.name, skill]));
	for (const name of selected) {
		const skill = byName.get(name);
		if (!skill) {
			return `Skill "${name}" is no longer in this agent's library.`;
		}
		if (!skill.enabled) {
			return `Skill "${name}" is disabled — enable it on the agent or remove it here.`;
		}
		if (skillBody(skill) === "") {
			return `Skill "${name}" has an empty body — compiled instructions need text.`;
		}
	}
	if (behaviorRequiresSkills(triggers) && selected.length === 0) {
		return "Add at least one skill: schedules, window triggers, and Behaviors with no trigger run on their compiled instructions alone.";
	}
	const bytes = compiledByteLength(
		compileBehaviorInstructions(selected, library),
	);
	if (bytes > MAX_COMPILED_INSTRUCTIONS_BYTES) {
		return `These skills compile to ${Math.round(bytes / 1024)}KB of instructions — the maximum is ${MAX_COMPILED_INSTRUCTIONS_BYTES / 1024}KB.`;
	}
	return null;
}

