import { useRef, useState } from "react";
import {
	MentionEditor,
	type MentionEditorHandle,
} from "@/components/agents/mention-editor";
import { useMentionSearch } from "@/components/agents/use-mention-search";
import { Label } from "@/components/ui/label";
import type { LobuRefKind } from "@/lib/references";
import { SqlSourceDialog, type SqlSourceValue } from "./sql-source-dialog";

/** Object kinds a watcher prompt can reference. Feeds/connections/metrics
 *  become the watcher's sources on save; entities/connectors scope context.
 *  SQL is offered via the synthetic `@sql` action (not a searchable kind). */
const WATCHER_MENTION_KINDS: LobuRefKind[] = [
	"entity",
	"connection",
	"connector",
	"feed",
	"metric",
];

interface TemplateFieldsEditorProps {
	prompt: string;
	onPromptChange: (value: string) => void;
}

export function TemplateFieldsEditor({
	prompt,
	onPromptChange,
}: TemplateFieldsEditorProps) {
	const searchRefs = useMentionSearch(WATCHER_MENTION_KINDS);
	const editorHandle = useRef<MentionEditorHandle | null>(null);

	// SQL dialog state. `editingPos` is the document position of the chip being
	// edited (undefined = creating a new one); `initial` seeds the dialog.
	const [sqlOpen, setSqlOpen] = useState(false);
	const [sqlInitial, setSqlInitial] = useState<SqlSourceValue | undefined>();
	const [editingPos, setEditingPos] = useState<number | undefined>();

	const openNewSql = () => {
		setSqlInitial(undefined);
		setEditingPos(undefined);
		setSqlOpen(true);
	};

	const openEditSql = (value: SqlSourceValue, pos: number) => {
		setSqlInitial(value);
		setEditingPos(pos);
		setSqlOpen(true);
	};

	const submitSql = (value: SqlSourceValue) => {
		editorHandle.current?.insertSql(value, editingPos);
	};

	return (
		<div className="space-y-2">
			<Label htmlFor="tfe-prompt">
				Goal <span className="text-destructive">*</span>
			</Label>
			<div className="rounded-lg border bg-background focus-within:ring-1 focus-within:ring-ring">
				<MentionEditor
					value={prompt}
					onChange={onPromptChange}
					// The watcher prompt is multi-line; Enter inserts a newline rather
					// than submitting (there's no send action here).
					onSubmit={() => {}}
					submitOnEnter={false}
					searchRefs={searchRefs}
					handleRef={editorHandle}
					onSqlRequest={openNewSql}
					onSqlEdit={openEditSql}
					placeholder="Describe what the agent should monitor, maintain, or accomplish… Type @ to reference a feed, connection, metric, entity, or SQL query."
					className="[&_.ProseMirror]:min-h-[7rem] [&_.ProseMirror]:max-h-72 [&_.ProseMirror]:overflow-y-auto"
				/>
			</div>
			<p className="text-xs text-muted-foreground">
				Type <span className="font-mono">@</span> to add feeds, connections,
				metrics, entities, or a SQL query as sources. They become the behavior's
				data on save.
			</p>
			<SqlSourceDialog
				open={sqlOpen}
				onOpenChange={setSqlOpen}
				initial={sqlInitial}
				onSubmit={submitSql}
			/>
		</div>
	);
}

