86				<div className="rounded-lg border bg-background focus-within:ring-1 focus-within:ring-ring">
87					<MentionEditor
88						value={value}
89						onChange={onChange}
90						// Instructions are multi-line and there is no send action here, so
91						// Enter inserts a newline instead of submitting.
92						onSubmit={() => {}}
93						submitOnEnter={false}
94						searchRefs={searchRefs}
95						placeholder={
96							hasSkills
97								? "What should this Behavior do? Type @ to use a skill."
98								: "What should this Behavior do?"
99						}
100						className="[&_.ProseMirror]:min-h-[7rem] [&_.ProseMirror]:max-h-72 [&_.ProseMirror]:overflow-y-auto"
101					/>
102				</div>
103	
104				{mentioned.length > 0 ? (
105					<div className="flex flex-wrap items-center gap-1.5">
106						{mentioned.map((name) => {
107							const isOutdated = outdated.includes(name);
108							const missing = !library.some((skill) => skill.name === name);
109							return (
110								<Badge
111									key={name}
112									variant={missing ? "destructive" : "secondary"}
113									className="font-normal"
114								>
115									{name}
116									{missing ? " · unavailable" : isOutdated ? " · newer text" : null}
117								</Badge>
118							);
119						})}
120					</div>
121				) : null}
122	
123				{outdated.length > 0 ? (
124					// The drift the snapshot model owes the author an answer to: the skill
125					// moved on, this Behavior did not. There is no separate "re-pin" action
126					// because saving already pins the library's CURRENT text — offering a
127					// button that does what Save does would imply they differ.
128					<p className="rounded-lg border border-dashed p-3 text-xs text-muted-foreground">
129						{outdated.length === 1
130							? `"${outdated[0]}" has been edited since this Behavior pinned it.`
131							: `${outdated.length} skills have been edited since this Behavior pinned them.`}{" "}
132						This Behavior keeps running the pinned text until you save it again.
133					</p>
134				) : null}
135	
136				{error ? (
137					<p className="text-xs text-destructive">{error}</p>
138				) : (
139					<p className="text-xs text-muted-foreground">
140						{hasSkills ? (
141							<>Type @ to pull in a skill; its text is saved with this version, so
142							later edits to the skill do not change this Behavior until you
143							update it.</>
144						) : agentId ? (
145							<>
146								This agent has no skills yet.{" "}
147								<Link
148									to="/$owner/agents/$agentId/skills"
149									params={{ owner, agentId }}
150									className="font-medium text-foreground underline underline-offset-2"
151								>
152									Add one
153								</Link>{" "}
154								to reuse instructions across Behaviors.
155							</>
156						) : (
157							"Pick an agent to reference its skills."
158						)}
159					</p>
160				)}
161			</div>
162		);
163	}

