import { describe, expect, it } from "vitest";
import {
	type BehaviorSkillOption,
	behaviorRequiresSkills,
	compileBehaviorInstructions,
	compiledByteLength,
	MAX_BEHAVIOR_SKILLS,
	MAX_COMPILED_INSTRUCTIONS_BYTES,
	selectableSkills,
	validateBehaviorSkills,
} from "./behavior-skills";

const skill = (
	name: string,
	over: Partial<BehaviorSkillOption> = {},
): BehaviorSkillOption => ({
	name,
	content: `body of ${name}`,
	enabled: true,
	...over,
});

const LIBRARY = [skill("triage"), skill("sql-style"), skill("digest")];

describe("compileBehaviorInstructions", () => {
	it("joins bodies in selection order with a blank line", () => {
		expect(compileBehaviorInstructions(["sql-style", "triage"], LIBRARY)).toBe(
			"body of sql-style\n\nbody of triage",
		);
	});

	it("returns empty text for an empty selection (the event-turn default)", () => {
		expect(compileBehaviorInstructions([], LIBRARY)).toBe("");
	});

	it("trims each body so the join is exactly one blank line", () => {
		const padded = [skill("a", { content: "\n  alpha  \n\n" }), skill("b")];
		expect(compileBehaviorInstructions(["a", "b"], padded)).toBe(
			"alpha\n\nbody of b",
		);
	});

	it("falls back to catalog instructions when a skill has no content", () => {
		const bundled = [
			skill("sys", { content: undefined, instructions: "bundled body" }),
		];
		expect(compileBehaviorInstructions(["sys"], bundled)).toBe("bundled body");
	});
});

describe("behaviorRequiresSkills", () => {
	it("requires a skill when there are no triggers (manual runs)", () => {
		expect(behaviorRequiresSkills([])).toBe(true);
		expect(behaviorRequiresSkills(undefined)).toBe(true);
	});

	it("requires a skill for a schedule trigger", () => {
		expect(behaviorRequiresSkills([{ kind: "schedule" }])).toBe(true);
	});

	it("requires a skill for an event trigger executing as a window", () => {
		expect(
			behaviorRequiresSkills([{ kind: "event", execution: "window" }]),
		).toBe(true);
	});

	it("allows zero skills for an event trigger executing as a turn", () => {
		expect(behaviorRequiresSkills([{ kind: "event", execution: "turn" }])).toBe(
			false,
		);
	});

	it("requires a skill when any one of several triggers needs it", () => {
		expect(
			behaviorRequiresSkills([
				{ kind: "event", execution: "turn" },
				{ kind: "schedule" },
			]),
		).toBe(true);
	});
});

describe("validateBehaviorSkills", () => {
	const turn = [{ kind: "event", execution: "turn" }];
	const schedule = [{ kind: "schedule" }];

	it("accepts a valid ordered selection", () => {
		expect(validateBehaviorSkills(["triage"], LIBRARY, schedule)).toBeNull();
	});

	it("accepts zero skills on an event-turn Behavior", () => {
		expect(validateBehaviorSkills([], LIBRARY, turn)).toBeNull();
	});

	it("rejects zero skills when the Behavior runs on instructions alone", () => {
		expect(validateBehaviorSkills([], LIBRARY, schedule)).toMatch(
			/at least one skill/i,
		);
	});

	it("rejects a duplicate skill", () => {
		expect(
			validateBehaviorSkills(["triage", "triage"], LIBRARY, schedule),
		).toMatch(/Duplicate skill: triage/);
	});

	it("rejects more than the maximum number of skills", () => {
		const many = Array.from({ length: MAX_BEHAVIOR_SKILLS + 1 }, (_, i) =>
			skill(`s${i}`),
		);
		const names = many.map((s) => s.name);
		expect(validateBehaviorSkills(names, many, schedule)).toMatch(
			new RegExp(`maximum is ${MAX_BEHAVIOR_SKILLS}`),
		);
	});

